  g:[{ t:'Câu hỏi chính phản: V 不 V / A 不 A', d:['Lặp động từ / tính từ ở dạng khẳng định + phủ định để hỏi: 是不是, 忙不忙, 懂不懂. Không thêm 吗 nữa.','Với 有: 有没有.'],
      ex:[['这|是不是|样品|？','zhè shì bu shì yàngpǐn?','Đây có phải hàng mẫu không?'],['你|懂不懂|？','nǐ dǒng bu dǒng?','Bạn hiểu không?'],['你|有没有|红|箱子|？','nǐ yǒu méiyǒu hóng xiāngzi?','Bạn có thùng đỏ không?']] },
    { t:'Hỏi màu: 什么颜色', d:['… 是什么颜色的？ → 是红的 / 绿的.'],
      ex:[['箱子|是|什么|颜色|的|？','xiāngzi shì shénme yánsè de?','Thùng màu gì?'],['不良品|放|在|红|箱子|里','bùliángpǐn fàng zài hóng xiāngzi lǐ','Hàng lỗi để trong thùng đỏ'],['你|会不会|说|汉语|？','nǐ huì bu huì shuō Hànyǔ?','Bạn có biết nói tiếng Trung không?']] }],
